local ADDON_NAME, ns = ...

-- Hints and better Do lines for quests, from Data/Hints.lua (generated by tools/hints/build.py from
-- forever-db's quest steps, triaged and reworded). Spec, Hint system: a Hint line shows only when a
-- quest has a known confusing step.
--
-- Do lines are keyed by the forever-db objective target's name ("Neru Fragment", "Kobold Vermin");
-- an objective matches when its name (text without the counter) contains that name, the same rule
-- the arrows use ("Kobold Vermin slain" contains "Kobold Vermin").

local Hints = {}
ns.Hints = Hints

local function data(questID)
  return ns.HintData and ns.HintData[questID]
end

---Hint texts for a quest, or nil.
---@param questID number
---@return string[]?
function Hints:For(questID)
  local entry = data(questID)
  if not entry or not entry.hints then
    return nil
  end
  local texts = {}
  for i, hint in ipairs(entry.hints) do
    texts[i] = hint[1]
  end
  return texts
end

---A better Do line for an objective, or nil.
---@param questID number
---@param objectiveName string objective text without its counter
---@return string?
---@return string? source forever-db step id
function Hints:DoFor(questID, objectiveName)
  local entry = data(questID)
  if not entry or not entry.objectives then
    return nil
  end
  local exact = entry.objectives[objectiveName]
  if exact then
    return exact[1], exact[2]
  end
  for target, line in pairs(entry.objectives) do
    if objectiveName:find(target, 1, true) then
      return line[1], line[2]
    end
  end
  return nil
end

---Every entry for a quest with its sources, for /qm quest.
---@param questID number
---@return table?
function Hints:Raw(questID)
  return data(questID)
end
